}

@media (prefers-color-scheme: dark) {
  .btn-cancel:hover:not(:disabled) {
    background-color: rgba(255, 255, 255, 0.05);
  }
}

.action-buttons {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* Fields & Form Control */
.field-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
