  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
}

.empty-icon {
  color: var(--text-muted);
  opacity: 0.5;
}

.empty-state h3 {
  font-size: 1.25rem;
  font-weight: 600;
  margin: 0;
}

.empty-state p {
  color: var(--text-muted);
  font-size: 0.925rem;
  margin: 0 0 0.5rem 0;
  max-width: 320px;
}

/* Toast Notifications */
.toast-notification {
  position: fixed;
  top: 1.5rem;
  right: 1.5rem;
  z-index: 1000;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.875rem 1.25rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  font-size: 0.875rem;
  font-weight: 500;
  animation: slideIn 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  border: 1px solid transparent;
}

@keyframes slideIn {
  from {
    transform: translateY(-1rem) scale(0.95);
    opacity: 0;
  }
  to {
    transform: translateY(0) scale(1);
    opacity: 1;
  }
}

.toast-success {
  background-color: #ecfdf5;
  color: #065f46;
  border-color: #a7f3d0;
}

@media (prefers-color-scheme: dark) {
  .toast-success {
    background-color: #064e3b;
    color: #a7f3d0;
    border-color: #047857;
  }
}

.toast-error {
  background-color: #fef2f2;
  color: #991b1b;
  border-color: #fca5a5;
}

@media (prefers-color-scheme: dark) {
  .toast-error {
    background-color: #7f1d1d;
    color: #fca5a5;
    border-color: #b91c1c;
  }
}

.toast-info {
  background-color: #eff6ff;
  color: #1e40af;
  border-color: #bfdbfe;
}

@media (prefers-color-scheme: dark) {
  .toast-info {
    background-color: #1e3a8a;
    color: #bfdbfe;
    border-color: #1d4ed8;
  }
}

.toast-icon {
  flex-shrink: 0;
}

.toast-message {
  flex-grow: 1;
}

.toast-close {
  background: none;
  border: none;
  font-size: 1.25rem;
  cursor: pointer;
  color: inherit;
  opacity: 0.6;
  padding: 0;
  line-height: 1;
}

.toast-close:hover {
  opacity: 1;
}

/* Footer */
.dashboard-footer {
  text-align: center;
  padding: 1.5rem 0;
  border-top: 1px solid var(--border-color);
  font-size: 0.85rem;
  color: var(--text-muted);
}

.dashboard-footer p {
  margin: 0;
}

